CREATE OR REPLACE FUNCTION public.can_read_bucket(b text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
            select case
                when b in ('product-images', 'branding') then true
                    when b = 'receipts' then public.is_staff()
                        when b = 'employee-documents' then public.has_any_role(array['hr_officer', 'manager'])
                            when b = 'contracts' then public.has_any_role(array['accountant', 'manager'])
                                else false
                                  end
                                  $function$
;
CREATE OR REPLACE FUNCTION public.can_write_bucket(b text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                    select case
                                        when b in ('product-images', 'branding') then public.has_any_role(array['manager'])
                                            when b = 'receipts' then public.is_staff()
                                                when b = 'employee-documents' then public.has_any_role(array['hr_officer', 'manager'])
                                                    when b = 'contracts' then public.has_any_role(array['accountant', 'manager'])
                                                        else false
                                                          end
                                                          $function$
;
