CREATE OR REPLACE FUNCTION public.fn_apply_stock_movement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                    begin
                                                      insert into public.stock_levels (store_id, item_id, quantity)
                                                        values (new.store_id, new.item_id, new.quantity)
                                                          on conflict (store_id, item_id) do update set quantity = public.stock_levels.quantity + excluded.quantity, updated_at = now();
                                                            return new;
                                                            end;
                                                            $function$
;
CREATE OR REPLACE FUNCTION public.fn_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                              begin
                                                                                                if tg_op = 'DELETE' then
                                                                                                    insert into public.audit_logs (table_name, record_id, action, old_data, user_id)
                                                                                                        values (tg_table_name, to_jsonb(old)->>'id', 'DELETE', to_jsonb(old), auth.uid());
                                                                                                            return old;
                                                                                                              elsif tg_op = 'UPDATE' then
                                                                                                                  insert into public.audit_logs (table_name, record_id, action, old_data, new_data, user_id)
                                                                                                                      values (tg_table_name, to_jsonb(new)->>'id', 'UPDATE', to_jsonb(old), to_jsonb(new), auth.uid());
                                                                                                                          return new;
                                                                                                                            else
                                                                                                                                insert into public.audit_logs (table_name, record_id, action, new_data, user_id)
                                                                                                                                    values (tg_table_name, to_jsonb(new)->>'id', 'INSERT', to_jsonb(new), auth.uid());
                                                                                                                                        return new;
                                                                                                                                          end if;
                                                                                                                                          end;
                                                                                                                                          $function$
;
CREATE OR REPLACE FUNCTION public.fn_batch_completed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                              declare
                                                                v_item uuid;
                                                                  v_yield numeric;
                                                                    r record;
                                                                    begin
                                                                      if new.status = 'completed' and old.status is distinct from 'completed' then
                                                                          new.completed_at := coalesce(new.completed_at, now());
                                                                              if new.store_id is not null then
                                                                                    select item_id into v_item from public.products where id = new.product_id;
                                                                                          select yield_quantity into v_yield from public.recipes where id = new.recipe_id;
                                                                                                if new.recipe_id is not null and v_yield is not null and (new.produced_qty + new.wasted_qty) > 0 then
                                                                                                        for r in select item_id, quantity from public.recipe_items where recipe_id = new.recipe_id loop
                                                                                                                  insert into public.stock_movements (store_id, item_id, movement_type, quantity, reference_type, reference_id, created_by)
                                                                                                                            values (new.store_id, r.item_id, 'production_out', -1 * round((r.quantity * (new.produced_qty + new.wasted_qty) / v_yield)::numeric, 3), 'production_batch', new.id, new.created_by);
                                                                                                                                    end loop;
                                                                                                                                          end if;
                                                                                                                                                if v_item is not null and new.produced_qty > 0 then
                                                                                                                                                        insert into public.stock_movements (store_id, item_id, movement_type, quantity, reference_type, reference_id, created_by)
                                                                                                                                                                values (new.store_id, v_item, 'production_in', new.produced_qty, 'production_batch', new.id, new.created_by);
                                                                                                                                                                      end if;
                                                                                                                                                                          end if;
                                                                                                                                                                            end if;
                                                                                                                                                                              return new;
                                                                                                                                                                              end;
                                                                                                                                                                              $function$
;
CREATE OR REPLACE FUNCTION public.fn_cash_transfer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                                                                                                                                                                                                    declare
                                                                                                                                                                                                                                                                                      v_from_branch uuid;
                                                                                                                                                                                                                                                                                        v_to_branch uuid;
                                                                                                                                                                                                                                                                                        begin
                                                                                                                                                                                                                                                                                          select branch_id into v_from_branch from public.cash_accounts where id = new.from_account_id;
                                                                                                                                                                                                                                                                                            select branch_id into v_to_branch from public.cash_accounts where id = new.to_account_id;
                                                                                                                                                                                                                                                                                              insert into public.cash_transactions (branch_id, cash_account_id, txn_type, amount, txn_date, description, reference_type, reference_id, created_by)
                                                                                                                                                                                                                                                                                                values (v_from_branch, new.from_account_id, 'out', new.amount, new.transfer_date, 'Transfer out', 'cash_transfer', new.id, new.created_by);
                                                                                                                                                                                                                                                                                                  insert into public.cash_transactions (branch_id, cash_account_id, txn_type, amount, txn_date, description, reference_type, reference_id, created_by)
                                                                                                                                                                                                                                                                                                    values (v_to_branch, new.to_account_id, 'in', new.amount, new.transfer_date, 'Transfer in', 'cash_transfer', new.id, new.created_by);
                                                                                                                                                                                                                                                                                                      return new;
                                                                                                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                                                                                                      $function$
;
CREATE OR REPLACE FUNCTION public.fn_close_day(p_branch uuid, p_date date, p_counted numeric, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                                                                                                                                                                                                                                                      declare
                                                                                                                                                                                                                                                                                                                                        v_open numeric;
                                                                                                                                                                                                                                                                                                                                          v_total numeric;
                                                                                                                                                                                                                                                                                                                                            v_cash_sales numeric;
                                                                                                                                                                                                                                                                                                                                              v_in numeric;
                                                                                                                                                                                                                                                                                                                                                v_out numeric;
                                                                                                                                                                                                                                                                                                                                                  v_expected numeric;
                                                                                                                                                                                                                                                                                                                                                    v_id uuid;
                                                                                                                                                                                                                                                                                                                                                    begin
                                                                                                                                                                                                                                                                                                                                                      if auth.uid() is not null and not public.has_any_role(array['cashier', 'accountant', 'manager']) then
                                                                                                                                                                                                                                                                                                                                                          raise exception 'Not allowed';
                                                                                                                                                                                                                                                                                                                                                            end if;
                                                                                                                                                                                                                                                                                                                                                              select counted_cash into v_open from public.daily_closings where branch_id = p_branch and closing_date < p_date order by closing_date desc limit 1;
                                                                                                                                                                                                                                                                                                                                                                v_open := coalesce(v_open, 0);
                                                                                                                                                                                                                                                                                                                                                                  select coalesce(sum(total_amount), 0) into v_total from public.sales where branch_id = p_branch and status = 'completed' and (sale_date at time zone 'Africa/Addis_Ababa')::date = p_date;
                                                                                                                                                                                                                                                                                                                                                                    select coalesce(sum(sp.amount), 0) into v_cash_sales from public.sale_payments sp join public.sales s on s.id = sp.sale_id where s.branch_id = p_branch and s.status = 'completed' and sp.method = 'cash' and (s.sale_date at time zone 'Africa/Addis_Ababa')::date = p_date;
                                                                                                                                                                                                                                                                                                                                                                      select coalesce(sum(t.amount) filter (where t.txn_type = 'in'), 0), coalesce(sum(t.amount) filter (where t.txn_type = 'out'), 0) into v_in, v_out
                                                                                                                                                                                                                                                                                                                                                                        from public.cash_transactions t join public.cash_accounts a on a.id = t.cash_account_id
                                                                                                                                                                                                                                                                                                                                                                          where t.branch_id = p_branch and t.txn_date = p_date and a.account_type = 'cash_drawer' and t.status = 'approved';
                                                                                                                                                                                                                                                                                                                                                                            v_expected := v_open + v_in - v_out;
                                                                                                                                                                                                                                                                                                                                                                              insert into public.daily_closings (branch_id, closing_date, opening_cash, total_sales, cash_sales, other_sales, total_cash_in, total_cash_out, expected_cash, counted_cash, closed_by, notes)
                                                                                                                                                                                                                                                                                                                                                                                values (p_branch, p_date, v_open, v_total, v_cash_sales, v_total - v_cash_sales, v_in, v_out, v_expected, p_counted, auth.uid(), p_notes)
                                                                                                                                                                                                                                                                                                                                                                                  on conflict (branch_id, closing_date) do update set opening_cash = excluded.opening_cash, total_sales = excluded.total_sales, cash_sales = excluded.cash_sales, other_sales = excluded.other_sales, total_cash_in = excluded.total_cash_in, total_cash_out = excluded.total_cash_out, expected_cash = excluded.expected_cash, counted_cash = excluded.counted_cash, closed_by = excluded.closed_by, notes = excluded.notes
                                                                                                                                                                                                                                                                                                                                                                                    returning id into v_id;
                                                                                                                                                                                                                                                                                                                                                                                      return v_id;
                                                                                                                                                                                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                                                                                                                                                                                      $function$
;
CREATE OR REPLACE FUNCTION public.fn_count_completed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                          declare
                                                                                            r record;
                                                                                            begin
                                                                                              for r in select item_id, (counted_qty - system_qty) as diff from public.stock_count_items where count_id = new.id loop
                                                                                                  if r.diff <> 0 then
                                                                                                        insert into public.stock_movements (store_id, item_id, movement_type, quantity, reference_type, reference_id, created_by)
                                                                                                              values (new.store_id, r.item_id, 'count', r.diff, 'stock_count', new.id, new.created_by);
                                                                                                                  end if;
                                                                                                                    end loop;
                                                                                                                      return new;
                                                                                                                      end;
                                                                                                                      $function$
;
CREATE OR REPLACE FUNCTION public.fn_generate_alerts()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                                                                                                                                                                                                                                                                                                      declare
                                                                                                                                                                                                                                                                                                                                                                                        v_n integer;
                                                                                                                                                                                                                                                                                                                                                                                          v_total integer := 0;
                                                                                                                                                                                                                                                                                                                                                                                          begin
                                                                                                                                                                                                                                                                                                                                                                                            if auth.uid() is not null and not public.has_any_role(array['manager', 'accountant']) then
                                                                                                                                                                                                                                                                                                                                                                                                raise exception 'Not allowed';
                                                                                                                                                                                                                                                                                                                                                                                                  end if;
                                                                                                                                                                                                                                                                                                                                                                                                    update public.rent_invoices set status = 'overdue' where status in ('unpaid', 'partial') and due_date < current_date;
                                                                                                                                                                                                                                                                                                                                                                                                      insert into public.notifications (role_code, type, title, body, data)
                                                                                                                                                                                                                                                                                                                                                                                                        select 'store_keeper', 'low_stock', 'Low stock: ' || v.name, 'Quantity ' || v.quantity::text || ' is at or below the minimum ' || v.min_stock::text, jsonb_build_object('item_id', v.id, 'key', 'low_stock:' || v.id::text || ':' || current_date::text)
                                                                                                                                                                                                                                                                                                                                                                                                          from public.v_low_stock v
                                                                                                                                                                                                                                                                                                                                                                                                            where not exists (select 1 from public.notifications n where n.type = 'low_stock' and n.data->>'key' = 'low_stock:' || v.id::text || ':' || current_date::text);
                                                                                                                                                                                                                                                                                                                                                                                                              get diagnostics v_n = row_count;
                                                                                                                                                                                                                                                                                                                                                                                                                v_total := v_total + v_n;
                                                                                                                                                                                                                                                                                                                                                                                                                  insert into public.notifications (role_code, type, title, body, data)
                                                                                                                                                                                                                                                                                                                                                                                                                    select 'accountant', 'overdue_credit', 'Overdue credit: ' || c.full_name, 'Balance ' || r.balance::text || ' was due on ' || r.due_date::text, jsonb_build_object('receivable_id', r.id, 'key', 'overdue_credit:' || r.id::text || ':' || current_date::text)
                                                                                                                                                                                                                                                                                                                                                                                                                      from public.receivables r join public.customers c on c.id = r.customer_id
                                                                                                                                                                                                                                                                                                                                                                                                                        where r.status in ('open', 'partial') and r.due_date < current_date
                                                                                                                                                                                                                                                                                                                                                                                                                            and not exists (select 1 from public.notifications n where n.type = 'overdue_credit' and n.data->>'key' = 'overdue_credit:' || r.id::text || ':' || current_date::text);
                                                                                                                                                                                                                                                                                                                                                                                                                              get diagnostics v_n = row_count;
                                                                                                                                                                                                                                                                                                                                                                                                                                v_total := v_total + v_n;
                                                                                                                                                                                                                                                                                                                                                                                                                                  insert into public.notifications (role_code, type, title, body, data)
                                                                                                                                                                                                                                                                                                                                                                                                                                    select 'accountant', 'rent_due', 'Rent due: ' || t.full_name, 'Invoice ' || ri.invoice_no || ' balance ' || (ri.amount - ri.paid_amount)::text || ' due ' || ri.due_date::text, jsonb_build_object('invoice_id', ri.id, 'key', 'rent_due:' || ri.id::text || ':' || current_date::text)
                                                                                                                                                                                                                                                                                                                                                                                                                                      from public.rent_invoices ri join public.tenants t on t.id = ri.tenant_id
                                                                                                                                                                                                                                                                                                                                                                                                                                        where ri.status in ('unpaid', 'partial', 'overdue') and ri.due_date <= current_date + 3
                                                                                                                                                                                                                                                                                                                                                                                                                                            and not exists (select 1 from public.notifications n where n.type = 'rent_due' and n.data->>'key' = 'rent_due:' || ri.id::text || ':' || current_date::text);
                                                                                                                                                                                                                                                                                                                                                                                                                                              get diagnostics v_n = row_count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                v_total := v_total + v_n;
                                                                                                                                                                                                                                                                                                                                                                                                                                                  insert into public.notifications (role_code, type, title, body, data)
                                                                                                                                                                                                                                                                                                                                                                                                                                                    select 'manager', 'lease_expiry', 'Lease expiring: ' || l.lease_no, 'Ends on ' || l.end_date::text, jsonb_build_object('lease_id', l.id, 'key', 'lease_expiry:' || l.id::text || ':' || current_date::text)
                                                                                                                                                                                                                                                                                                                                                                                                                                                      from public.leases l
                                                                                                                                                                                                                                                                                                                                                                                                                                                        where l.status = 'active' and l.end_date between current_date and current_date + 30
                                                                                                                                                                                                                                                                                                                                                                                                                                                            and not exists (select 1 from public.notifications n where n.type = 'lease_expiry' and n.data->>'key' = 'lease_expiry:' || l.id::text || ':' || current_date::text);
                                                                                                                                                                                                                                                                                                                                                                                                                                                              get diagnostics v_n = row_count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_total := v_total + v_n;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  insert into public.notifications (role_code, type, title, body, data)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    select 'accountant', 'bill_due', 'Bill due: ' || b.bill_no, 'Balance ' || (b.amount - b.paid_amount)::text || ' due ' || b.due_date::text, jsonb_build_object('bill_id', b.id, 'key', 'bill_due:' || b.id::text || ':' || current_date::text)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      from public.bills b
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        where b.status in ('unpaid', 'partial') and b.due_date is not null and b.due_date <= current_date + 3
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            and not exists (select 1 from public.notifications n where n.type = 'bill_due' and n.data->>'key' = 'bill_due:' || b.id::text || ':' || current_date::text);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              get diagnostics v_n = row_count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_total := v_total + v_n;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return v_total;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $function$
;
CREATE OR REPLACE FUNCTION public.fn_generate_payroll(p_run_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                declare
                                                  v_run public.payroll_runs%rowtype;
                                                    e record;
                                                      v_allow numeric;
                                                        v_gross numeric;
                                                          v_pension numeric;
                                                            v_taxable numeric;
                                                              v_tax numeric;
                                                                v_adv numeric;
                                                                begin
                                                                  if auth.uid() is not null and not public.has_any_role(array['hr_officer', 'accountant']) then
                                                                      raise exception 'Not allowed';
                                                                        end if;
                                                                          select * into v_run from public.payroll_runs where id = p_run_id;
                                                                            if not found then
                                                                                raise exception 'Payroll run not found';
                                                                                  end if;
                                                                                    if v_run.status <> 'draft' then
                                                                                        raise exception 'Only a draft payroll can be generated';
                                                                                          end if;
                                                                                            delete from public.payslips where payroll_run_id = p_run_id;
                                                                                              for e in select * from public.employees where status in ('active', 'on_leave') and (v_run.branch_id is null or branch_id = v_run.branch_id) loop
                                                                                                  v_allow := e.transport_allowance + e.housing_allowance + e.other_allowance;
                                                                                                      v_gross := e.base_salary + v_allow;
                                                                                                          v_pension := round(e.base_salary * e.pension_rate / 100, 2);
                                                                                                              v_taxable := v_gross - v_pension;
                                                                                                                  select greatest(round(v_taxable * tb.rate / 100 - tb.deduction, 2), 0) into v_tax
                                                                                                                      from public.tax_brackets tb
                                                                                                                          where v_taxable >= tb.min_amount and (tb.max_amount is null or v_taxable <= tb.max_amount)
                                                                                                                              order by tb.min_amount desc limit 1;
                                                                                                                                  v_tax := coalesce(v_tax, 0);
                                                                                                                                      select coalesce(least(sum(a.monthly_deduction), sum(a.balance)), 0) into v_adv from public.employee_advances a where a.employee_id = e.id and a.status = 'active';
                                                                                                                                          insert into public.payslips (payroll_run_id, employee_id, base_salary, allowances, gross_pay, income_tax, pension_employee, advance_deduction, total_deductions, net_pay)
                                                                                                                                              values (p_run_id, e.id, e.base_salary, v_allow, v_gross, v_tax, v_pension, v_adv, v_tax + v_pension + v_adv, v_gross - v_tax - v_pension - v_adv);
                                                                                                                                                end loop;
                                                                                                                                                  update public.payroll_runs set
                                                                                                                                                      total_gross = coalesce((select sum(gross_pay) from public.payslips where payroll_run_id = p_run_id), 0),
                                                                                                                                                          total_deductions = coalesce((select sum(total_deductions) from public.payslips where payroll_run_id = p_run_id), 0),
                                                                                                                                                              total_net = coalesce((select sum(net_pay) from public.payslips where payroll_run_id = p_run_id), 0)
                                                                                                                                                                where id = p_run_id;
                                                                                                                                                                end;
                                                                                                                                                                $function$
;
CREATE OR REPLACE FUNCTION public.fn_generate_rent_invoices(p_date date DEFAULT CURRENT_DATE)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                                                                                                                                                                                                        declare
                                                                                                                                                                                                                                                                                          v_start date := date_trunc('month', p_date)::date;
                                                                                                                                                                                                                                                                                            v_count integer;
                                                                                                                                                                                                                                                                                            begin
                                                                                                                                                                                                                                                                                              if auth.uid() is not null and not public.has_any_role(array['manager', 'accountant']) then
                                                                                                                                                                                                                                                                                                  raise exception 'Not allowed';
                                                                                                                                                                                                                                                                                                    end if;
                                                                                                                                                                                                                                                                                                      insert into public.rent_invoices (invoice_no, lease_id, tenant_id, property_id, period_start, period_end, amount, due_date)
                                                                                                                                                                                                                                                                                                        select 'RI-' || to_char(v_start, 'YYYYMM') || '-' || l.lease_no, l.id, l.tenant_id, l.property_id, v_start,
                                                                                                                                                                                                                                                                                                            (v_start + make_interval(months => case l.billing_frequency when 'monthly' then 1 when 'quarterly' then 3 else 12 end))::date - 1,
                                                                                                                                                                                                                                                                                                                l.rent_amount, v_start + 5
                                                                                                                                                                                                                                                                                                                  from public.leases l
                                                                                                                                                                                                                                                                                                                    where l.status = 'active'
                                                                                                                                                                                                                                                                                                                        and l.start_date <= (v_start + interval '1 month')::date - 1
                                                                                                                                                                                                                                                                                                                            and l.end_date >= v_start
                                                                                                                                                                                                                                                                                                                                and mod(((extract(year from v_start) * 12 + extract(month from v_start)) - (extract(year from l.start_date) * 12 + extract(month from l.start_date)))::integer, case l.billing_frequency when 'monthly' then 1 when 'quarterly' then 3 else 12 end) = 0
                                                                                                                                                                                                                                                                                                                                  on conflict (lease_id, period_start) do nothing;
                                                                                                                                                                                                                                                                                                                                    get diagnostics v_count = row_count;
                                                                                                                                                                                                                                                                                                                                      return v_count;
                                                                                                                                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                                                                                                                                      $function$
;
