CREATE OR REPLACE FUNCTION public.fn_payable_payment_apply()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                                                                        declare
                                                                                                                                                          v_supplier uuid;
                                                                                                                                                            v_bill uuid;
                                                                                                                                                            begin
                                                                                                                                                              update public.payables set paid_amount = paid_amount + new.amount,
                                                                                                                                                                  status = case when paid_amount + new.amount >= amount then 'paid' else 'partial' end
                                                                                                                                                                    where id = new.payable_id and status <> 'cancelled';
                                                                                                                                                                      select supplier_id, bill_id into v_supplier, v_bill from public.payables where id = new.payable_id;
                                                                                                                                                                        insert into public.ledger_entries (party_type, supplier_id, description, debit, reference_type, reference_id)
                                                                                                                                                                          values ('supplier', v_supplier, 'Payment made', new.amount, 'payable_payment', new.id);
                                                                                                                                                                            if v_bill is not null then
                                                                                                                                                                                update public.bills set paid_amount = paid_amount + new.amount,
                                                                                                                                                                                      status = case when paid_amount + new.amount >= amount then 'paid' else 'partial' end
                                                                                                                                                                                          where id = v_bill;
                                                                                                                                                                                            end if;
                                                                                                                                                                                              if new.cash_account_id is not null then
                                                                                                                                                                                                  insert into public.cash_transactions (cash_account_id, txn_type, amount, txn_date, description, method, reference_type, reference_id, created_by)
                                                                                                                                                                                                      values (new.cash_account_id, 'out', new.amount, new.payment_date, 'Supplier payment', new.method, 'payable_payment', new.id, new.paid_by);
                                                                                                                                                                                                        end if;
                                                                                                                                                                                                          return new;
                                                                                                                                                                                                          end;
                                                                                                                                                                                                          $function$
;
CREATE OR REPLACE FUNCTION public.fn_payroll_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                                                                                declare
                                                                                                                                                                  v_cat uuid;
                                                                                                                                                                    r record;
                                                                                                                                                                      a record;
                                                                                                                                                                        v_left numeric;
                                                                                                                                                                          v_apply numeric;
                                                                                                                                                                          begin
                                                                                                                                                                            if new.status = 'approved' and old.status is distinct from 'approved' then
                                                                                                                                                                                new.approved_at := coalesce(new.approved_at, now());
                                                                                                                                                                                    new.approved_by := coalesce(new.approved_by, auth.uid());
                                                                                                                                                                                      end if;
                                                                                                                                                                                        if new.status = 'paid' and old.status is distinct from 'paid' then
                                                                                                                                                                                            new.paid_at := coalesce(new.paid_at, now());
                                                                                                                                                                                                update public.payslips set is_paid = true, paid_at = now() where payroll_run_id = new.id;
                                                                                                                                                                                                    for r in select employee_id, advance_deduction from public.payslips where payroll_run_id = new.id and advance_deduction > 0 loop
                                                                                                                                                                                                          v_left := r.advance_deduction;
                                                                                                                                                                                                                for a in select id, balance from public.employee_advances where employee_id = r.employee_id and status = 'active' order by advance_date, created_at loop
                                                                                                                                                                                                                        exit when v_left <= 0;
                                                                                                                                                                                                                                v_apply := least(a.balance, v_left);
                                                                                                                                                                                                                                        update public.employee_advances set balance = balance - v_apply, status = case when balance - v_apply <= 0 then 'settled' else 'active' end where id = a.id;
                                                                                                                                                                                                                                                v_left := v_left - v_apply;
                                                                                                                                                                                                                                                      end loop;
                                                                                                                                                                                                                                                          end loop;
                                                                                                                                                                                                                                                              if new.cash_account_id is not null and new.total_net > 0 then
                                                                                                                                                                                                                                                                    select id into v_cat from public.expense_categories where name = 'Salaries';
                                                                                                                                                                                                                                                                          insert into public.cash_transactions (branch_id, cash_account_id, txn_type, category_id, amount, description, reference_type, reference_id, created_by)
                                                                                                                                                                                                                                                                                values (new.branch_id, new.cash_account_id, 'out', v_cat, new.total_net, 'Payroll ' || to_char(new.period_month, 'YYYY-MM'), 'payroll_run', new.id, new.created_by);
                                                                                                                                                                                                                                                                                    end if;
                                                                                                                                                                                                                                                                                      end if;
                                                                                                                                                                                                                                                                                        return new;
                                                                                                                                                                                                                                                                                        end;
                                                                                                                                                                                                                                                                                        $function$
;
CREATE OR REPLACE FUNCTION public.fn_po_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                                                                                                              declare
                                                                                                                                                                                                v_po uuid;
                                                                                                                                                                                                  v_sum numeric;
                                                                                                                                                                                                  begin
                                                                                                                                                                                                    if tg_op = 'DELETE' then
                                                                                                                                                                                                        v_po := old.po_id;
                                                                                                                                                                                                          else
                                                                                                                                                                                                              v_po := new.po_id;
                                                                                                                                                                                                                end if;
                                                                                                                                                                                                                  select coalesce(sum(line_total), 0) into v_sum from public.purchase_order_items where po_id = v_po;
                                                                                                                                                                                                                    update public.purchase_orders set subtotal = v_sum, total_amount = v_sum + tax_amount where id = v_po;
                                                                                                                                                                                                                      return null;
                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                      $function$
;
