 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
            begin
              if auth.uid() is not null and not public.is_admin() then
                  if new.role_code is distinct from old.role_code or new.is_active is distinct from old.is_active or new.branch_id is distinct from old.branch_id then
                        raise exception 'Only an administrator can change role, status or branch';
                            end if;
                              end if;
                                return new;
                                end;
                                $function$
;
CREATE OR REPLACE FUNCTION public.fn_receipt_item_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                                                                                                                                                                    declare
                                                                                                                                                                                                                                                      v_store uuid;
                                                                                                                                                                                                                                                        v_po uuid;
                                                                                                                                                                                                                                                          v_by uuid;
                                                                                                                                                                                                                                                          begin
                                                                                                                                                                                                                                                            select store_id, po_id, received_by into v_store, v_po, v_by from public.goods_receipts where id = new.receipt_id;
                                                                                                                                                                                                                                                              insert into public.stock_movements (store_id, item_id, movement_type, quantity, unit_cost, reference_type, reference_id, batch_no, expiry_date, created_by)
                                                                                                                                                                                                                                                                values (v_store, new.item_id, 'purchase', new.quantity, new.unit_cost, 'goods_receipt', new.receipt_id, new.batch_no, new.expiry_date, v_by);
                                                                                                                                                                                                                                                                  update public.items set cost_price = new.unit_cost where id = new.item_id and new.unit_cost > 0;
                                                                                                                                                                                                                                                                    if v_po is not null then
                                                                                                                                                                                                                                                                        update public.purchase_order_items set quantity_received = quantity_received + new.quantity where po_id = v_po and item_id = new.item_id;
                                                                                                                                                                                                                                                                            update public.purchase_orders set status = case when exists (select 1 from public.purchase_order_items where po_id = v_po and quantity_received < quantity_ordered) then 'partial' else 'received' end
                                                                                                                                                                                                                                                                                where id = v_po and status in ('ordered', 'partial');
                                                                                                                                                                                                                                                                                  end if;
                                                                                                                                                                                                                                                                                    return new;
                                                                                                                                                                                                                                                                                    end;
                                                                                                                                                                                                                                                                                    $function$
;
