CREATE OR REPLACE FUNCTION public.fn_write_off_approved()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                                                                                                                                            declare
                                                                                                                                                                                                                              v_cust uuid;
                                                                                                                                                                                                                              begin
                                                                                                                                                                                                                                update public.receivables set status = 'written_off' where id = new.receivable_id;
                                                                                                                                                                                                                                  select customer_id into v_cust from public.receivables where id = new.receivable_id;
                                                                                                                                                                                                                                    insert into public.ledger_entries (party_type, customer_id, description, credit, reference_type, reference_id)
                                                                                                                                                                                                                                      values ('customer', v_cust, 'Write-off approved', new.amount, 'write_off', new.id);
                                                                                                                                                                                                                                        return new;
                                                                                                                                                                                                                                        end;
                                                                                                                                                                                                                                        $function$
;
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      declare
        v_role text := 'customer';
        begin
          if not exists (select 1 from public.profiles) then
              v_role := 'admin';
                end if;
                  insert into public.profiles (id, full_name, email, phone, role_code)
                    values (new.id, coalesce(new.raw_user_meta_data->>'full_name', split_part(coalesce(new.email, ''), '@', 1)), new.email, new.phone, v_role)
                      on conflict (id) do nothing;
                        return new;
                        end;
                        $function$
;
CREATE OR REPLACE FUNCTION public.has_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.profiles where role_code = 'admin' and is_active)
  $function$
;
CREATE OR REPLACE FUNCTION public.has_any_role(roles text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
        select coalesce((select (role_code = any(roles)) or role_code = 'admin' from public.profiles where id = auth.uid() and is_active), false)
        $function$
;
CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select coalesce((select role_code = 'admin' from public.profiles where id = auth.uid() and is_active), false)
    $function$
;
CREATE OR REPLACE FUNCTION public.is_staff()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      select coalesce((select role_code <> 'customer' from public.profiles where id = auth.uid() and is_active), false)
      $function$
;
CREATE OR REPLACE FUNCTION public.next_number(p_prefix text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
        declare
          v bigint;
          begin
            insert into public.number_sequences (prefix, last_value) values (p_prefix, 1)
              on conflict (prefix) do update set last_value = public.number_sequences.last_value + 1
                returning last_value into v;
                  return p_prefix || '-' || lpad(v::text, 6, '0');
                  end;
                  $function$
;
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
    return new;
    end;
    $function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      declare
        v_role text := 'customer';
        begin
          if not exists (select 1 from public.profiles) then
              v_role := 'admin';
                end if;
                  insert into public.profiles (id, full_name, email, phone, role_code)
                    values (new.id, coalesce(new.raw_user_meta_data->>'full_name', split_part(coalesce(new.email, ''), '@', 1)), new.email, new.phone, v_role)
                      on conflict (id) do nothing;
                        return new;
                        end;
                        $function$
;

create or replace view public."v_cash_account_balances" as
 SELECT a.id,
    a.branch_id,
    a.name,
    a.account_type,
    a.opening_balance,
    COALESCE(sum(t.amount) FILTER (WHERE (t.txn_type = 'in'::text)), (0)::numeric) AS total_in,
    COALESCE(sum(t.amount) FILTER (WHERE (t.txn_type = 'out'::text)), (0)::numeric) AS total_out,
    ((a.opening_balance + COALESCE(sum(t.amount) FILTER (WHERE (t.txn_type = 'in'::text)), (0)::numeric)) - COALESCE(sum(t.amount) FILTER (WHERE (t.txn_type = 'out'::text)), (0)::numeric)) AS balance
   FROM (cash_accounts a
     LEFT JOIN cash_transactions t ON (((t.cash_account_id = a.id) AND (t.status = 'approved'::text))))
  GROUP BY a.id;
create or replace view public."v_customer_balances" as
 SELECT c.id AS customer_id,
    c.full_name,
    COALESCE(sum(l.debit), (0)::numeric) AS total_debit,
    COALESCE(sum(l.credit), (0)::numeric) AS total_credit,
    (COALESCE(sum(l.debit), (0)::numeric) - COALESCE(sum(l.credit), (0)::numeric)) AS balance_owed
   FROM (customers c
     LEFT JOIN ledger_entries l ON ((l.customer_id = c.id)))
  GROUP BY c.id;
create or replace view public."v_daily_sales" as
 SELECT ((sale_date AT TIME ZONE 'Africa/Addis_Ababa'::text))::date AS sale_day,
    branch_id,
    count(*) AS sales_count,
    sum(subtotal) AS subtotal,
    sum(discount_amount) AS discounts,
    sum(tax_amount) AS tax,
    sum(total_amount) AS total_sales,
    sum(paid_amount) AS paid
   FROM sales s
  WHERE (status = 'completed'::text)
  GROUP BY (((sale_date AT TIME ZONE 'Africa/Addis_Ababa'::text))::date), branch_id;
create or replace view public."v_expense_summary" as
 SELECT (date_trunc('month'::text, (t.txn_date)::timestamp with time zone))::date AS month,
    COALESCE(c.name, 'Uncategorized'::text) AS category,
    t.txn_type,
    sum(t.amount) AS total
   FROM (cash_transactions t
     LEFT JOIN expense_categories c ON ((c.id = t.category_id)))
  WHERE (t.status = 'approved'::text)
  GROUP BY ((date_trunc('month'::text, (t.txn_date)::timestamp with time zone))::date), COALESCE(c.name, 'Uncategorized'::text), t.txn_type;
create or replace view public."v_low_stock" as
 SELECT i.id,
    i.sku,
    i.name,
    i.min_stock,
    COALESCE(sum(l.quantity), (0)::numeric) AS quantity
   FROM (items i
     LEFT JOIN stock_levels l ON ((l.item_id = i.id)))
  WHERE (i.is_active AND (i.min_stock > (0)::numeric))
  GROUP BY i.id
 HAVING (COALESCE(sum(l.quantity), (0)::numeric) <= i.min_stock);
create or replace view public."v_payable_aging" as
 SELECT s.id AS supplier_id,
    s.name,
    COALESCE(sum(p.balance) FILTER (WHERE ((p.due_date IS NULL) OR (p.due_date >= CURRENT_DATE))), (0)::numeric) AS not_due,
    COALESCE(sum(p.balance) FILTER (WHERE (((CURRENT_DATE - p.due_date) >= 1) AND ((CURRENT_DATE - p.due_date) <= 30))), (0)::numeric) AS days_1_30,
    COALESCE(sum(p.balance) FILTER (WHERE (((CURRENT_DATE - p.due_date) >= 31) AND ((CURRENT_DATE - p.due_date) <= 60))), (0)::numeric) AS days_31_60,
    COALESCE(sum(p.balance) FILTER (WHERE (((CURRENT_DATE - p.due_date) >= 61) AND ((CURRENT_DATE - p.due_date) <= 90))), (0)::numeric) AS days_61_90,
    COALESCE(sum(p.balance) FILTER (WHERE ((CURRENT_DATE - p.due_date) > 90)), (0)::numeric) AS over_90,
    COALESCE(sum(p.balance), (0)::numeric) AS total_balance
   FROM (suppliers s
     JOIN payables p ON (((p.supplier_id = s.id) AND (p.status = ANY (ARRAY['open'::text, 'partial'::text])))))
  GROUP BY s.id, s.name;
create or replace view public."v_payroll_summary" as
 SELECT r.id AS payroll_run_id,
    r.period_month,
    r.status,
    r.branch_id,
    count(p.id) AS employees,
    COALESCE(sum(p.gross_pay), (0)::numeric) AS gross,
    COALESCE(sum(p.total_deductions), (0)::numeric) AS deductions,
    COALESCE(sum(p.net_pay), (0)::numeric) AS net
   FROM (payroll_runs r
     LEFT JOIN payslips p ON ((p.payroll_run_id = r.id)))
  GROUP BY r.id;
create or replace view public."v_product_sales" as
 SELECT p.id AS product_id,
    p.name AS product_name,
    ((s.sale_date AT TIME ZONE 'Africa/Addis_Ababa'::text))::date AS sale_day,
    sum(si.quantity) AS quantity_sold,
    sum(si.line_total) AS revenue
   FROM ((sale_items si
     JOIN sales s ON (((s.id = si.sale_id) AND (s.status = 'completed'::text))))
     JOIN products p ON ((p.id = si.product_id)))
  GROUP BY p.id, p.name, (((s.sale_date AT TIME ZONE 'Africa/Addis_Ababa'::text))::date);
create or replace view public."v_receivable_aging" as
 SELECT c.id AS customer_id,
    c.full_name,
    COALESCE(sum(r.balance) FILTER (WHERE ((r.due_date IS NULL) OR (r.due_date >= CURRENT_DATE))), (0)::numeric) AS not_due,
    COALESCE(sum(r.balance) FILTER (WHERE (((CURRENT_DATE - r.due_date) >= 1) AND ((CURRENT_DATE - r.due_date) <= 30))), (0)::numeric) AS days_1_30,
    COALESCE(sum(r.balance) FILTER (WHERE (((CURRENT_DATE - r.due_date) >= 31) AND ((CURRENT_DATE - r.due_date) <= 60))), (0)::numeric) AS days_31_60,
    COALESCE(sum(r.balance) FILTER (WHERE (((CURRENT_DATE - r.due_date) >= 61) AND ((CURRENT_DATE - r.due_date) <= 90))), (0)::numeric) AS days_61_90,
    COALESCE(sum(r.balance) FILTER (WHERE ((CURRENT_DATE - r.due_date) > 90)), (0)::numeric) AS over_90,
    COALESCE(sum(r.balance), (0)::numeric) AS total_balance
   FROM (customers c
     JOIN receivables r ON (((r.customer_id = c.id) AND (r.status = ANY (ARRAY['open'::text, 'partial'::text])))))
  GROUP BY c.id, c.full_name;
create or replace view public."v_rent_status" as
 SELECT ri.id,
    ri.invoice_no,
    ri.period_start,
    ri.period_end,
    ri.amount,
    ri.paid_amount,
    (ri.amount - ri.paid_amount) AS balance,
    ri.due_date,
    ri.status,
    t.full_name AS tenant_name,
    pr.name AS property_name,
    GREATEST((CURRENT_DATE - ri.due_date), 0) AS days_overdue
   FROM ((rent_invoices ri
     JOIN tenants t ON ((t.id = ri.tenant_id)))
     JOIN properties pr ON ((pr.id = ri.property_id)));
create or replace view public."v_stock_valuation" as
 SELECT l.store_id,
    s.name AS store_name,
    l.item_id,
    i.sku,
    i.name AS item_name,
    l.quantity,
    i.cost_price,
    round((l.quantity * i.cost_price), 2) AS stock_value
   FROM ((stock_levels l
     JOIN items i ON ((i.id = l.item_id)))
     JOIN stores s ON ((s.id = l.store_id)));
create or replace view public."v_supplier_balances" as
 SELECT s.id AS supplier_id,
    s.name,
    COALESCE(sum(l.credit), (0)::numeric) AS total_credit,
    COALESCE(sum(l.debit), (0)::numeric) AS total_paid,
    (COALESCE(sum(l.credit), (0)::numeric) - COALESCE(sum(l.debit), (0)::numeric)) AS balance_we_owe
   FROM (suppliers s
     LEFT JOIN ledger_entries l ON ((l.supplier_id = s.id)))
  GROUP BY s.id;
create or replace view public."v_dashboard_kpis" as
 SELECT ( SELECT COALESCE(sum(sales.total_amount), (0)::numeric) AS "coalesce"
           FROM sales
          WHERE ((sales.status = 'completed'::text) AND (((sales.sale_date AT TIME ZONE 'Africa/Addis_Ababa'::text))::date = ((now() AT TIME ZONE 'Africa/Addis_Ababa'::text))::date))) AS today_sales,
    ( SELECT COALESCE(sum(v_cash_account_balances.balance), (0)::numeric) AS "coalesce"
           FROM v_cash_account_balances) AS cash_balance,
    ( SELECT count(*) AS count
           FROM v_low_stock) AS low_stock_items,
    ( SELECT COALESCE(sum(receivables.balance), (0)::numeric) AS "coalesce"
           FROM receivables
          WHERE ((receivables.status = ANY (ARRAY['open'::text, 'partial'::text])) AND (receivables.due_date < CURRENT_DATE))) AS overdue_receivables,
    ( SELECT COALESCE(sum((rent_invoices.amount - rent_invoices.paid_amount)), (0)::numeric) AS "coalesce"
           FROM rent_invoices
          WHERE ((rent_invoices.status = ANY (ARRAY['unpaid'::text, 'partial'::text, 'overdue'::text])) AND (rent_invoices.due_date <= (CURRENT_DATE + 7)))) AS rent_due,
    ( SELECT count(*) AS count
           FROM attendance
          WHERE ((attendance.work_date = CURRENT_DATE) AND (attendance.status = ANY (ARRAY['present'::text, 'late'::text])))) AS staff_present_today;

