drop policy if exists "bakery_storage_insert" on "storage"."objects";
create policy "bakery_storage_insert" on "storage"."objects" as permissive for insert to authenticated with check (can_write_bucket(bucket_id));
drop policy if exists "bakery_storage_select" on "storage"."objects";
