drop policy if exists "bakery_storage_update" on "storage"."objects";
create policy "bakery_storage_update" on "storage"."objects" as permissive for update to authenticated using (can_write_bucket(bucket_id)) with check (can_write_bucket(bucket_id));

grant usage on schema public to anon, authenticated;
grant all on all tables in schema public to anon, authenticated;
grant all on all sequences in schema public to anon, authenticated;
